 host.innerHTML=`<summary><strong>Evidence fixes and independent answer executors · research only</strong></summary><p>The live matcher remains unchanged. Rules and answer executors are evaluated in separate paired studies. Both 1,000-model cohorts retain their own denominators.</p><div class="benchmark-controls"><label>Study<select id="paired-study"><option value="fixes076">Evidence fixes · 0.75 → 0.76</option><option value="executors077">Full questionnaire: existing frozen answers versus Grok</option><option value="targeted077">New targeted follow-ups only: frozen earlier context</option></select></label><label>Cohort<select id="paired-cohort"><option value="all">All original models · 1,000</option><option value="development">Original development · 758</option><option value="holdout">Original holdout · 30</option><option value="holdout049">Earlier fresh holdout · 12</option><option value="holdout056">Expansion holdout · 200</option><option value="grok075">Grok-authored cohort · 1,000</option></select></label><label>Education<select id="paired-education"><option value="all">Every education route</option><option value="degree">Bachelor + graduate</option><option value="college">Bachelor</option><option value="graduate">Graduate / professional</option><option value="program">Associate / specialist</option><option value="work">Learn at work</option><option value="apprenticeship">Apprenticeship</option></select></label><label>Cases<select id="paired-cases"><option value="changed">Changed career lists</option><option value="all">Every model</option><option value="no-top">No final supported Top</option><option value="no-degree">No final bachelor / graduate Top</option></select></label><label>Find profile<input id="paired-query" type="search" placeholder="Name or ID"></label></div><div id="paired-status" role="status"></div><div id="paired-totals"></div><div class="table-scroll"><table><thead><tr><th>Model and profile</th><th id="paired-before-label"></th><th id="paired-after-label"></th><th>Evidence and remaining uncertainty</th></tr></thead><tbody id="paired-body"></tbody></table></div><div class="pagination"><button id="paired-prev">Previous</button><span id="paired-page"></span><button id="paired-next">Next</button><button id="paired-csv">Download this view · CSV</button></div><p><a href="./evidence-benchmark-076.json.gz">Download the complete rule comparison</a> · <a href="./executor-comparison-077.json.gz">Download the executor comparison manifest</a> · <a href="./executor-answers-077.json.gz">Sealed Grok answer codes</a> · <a href="./executor-profiles-077.json.gz">Frozen profiles, question bank and existing answers</a> · <a href="./executor-protocol-077.json">Run protocol</a></p><p>Research 0.76 is post-holdout calibration: the reviewed Grok cases informed its rules. The response-executor comparison uses the identical current 0.63 matcher on both sides. A Top label means the matching rules accept the generated answers; it does not independently validate the inferred interests. More matches from an AI answer executor are not proof of better matching. Unknown interests remain unknown in the rule study.</p>`;
 const $=id=>document.getElementById(id);$('paired-study').value=['executors077','targeted077'].includes(params.get('study'))?params.get('study'):'fixes076';$('paired-cohort').value=params.get('researchCohort')||(fixes.rows.some(r=>r.cohort==='grok075'&&r.id===(params.get('researchQuery')||params.get('query')))?'grok075':'all');$('paired-query').value=params.get('researchQuery')||params.get('query')||'';$('paired-cases').value=params.get('researchCase')||(params.get('query')||params.get('researchQuery')?'all':'changed');$('paired-education').value=params.get('researchEducation')||'all';let page=0,filtered=[],renderEpoch=0;const caseCache=new Map();
