 const d=isFix?fixes:comparison,g=$('paired-cohort').value,edu=$('paired-education').value,kind=$('paired-cases').value,q=$('paired-query').value.toLowerCase(),scope=d.rows.filter(r=>g==='all'?r.cohort!=='grok075':r.cohort===g),before=r=>isFix?r.beforeTop:r.simulator.top,after=r=>isFix?r.afterTop:r.grok.top,support=r=>isFix?r.afterSupported:r.grok.supported,changed=r=>isFix?r.added.length||r.withdrawn.length||JSON.stringify(before(r).map(p=>p.id))!==JSON.stringify(after(r).map(p=>p.id)):!r.exactTopSet;
