 $('paired-totals').innerHTML=[['Supported Top',ps=>ps.length>0],['Bachelor / graduate Top',ps=>ps.some(degree)],['Graduate Top',ps=>ps.some(p=>p.routes.some(r=>r.key==='graduate'))],['Top covers lifestyle',ps=>ps.some(p=>p.budget.covers===true)]].map(([label,pred])=>{const a=scope.filter(r=>pred(before(r))).length,b=scope.filter(r=>pred(after(r))).length;return `<p><strong>${label}: ${a} → ${b} / ${scope.length}</strong></p>`;}).join('')+(!isFix?`<p>Same Top set: ${scope.filter(r=>r.exactTopSet).length} / ${scope.length}. Changed scoring codes: ${scope.reduce((n,r)=>n+r.changedAnswers,0)} / ${scope.reduce((n,r)=>n+r.questions,0)}. Empty/empty sets count as agreement.</p>`:'');
