 let visible=filtered.slice(page*20,page*20+20);if(d.detailParts){const urls=[...new Set(visible.map(r=>r.detailPart))];const details=new Map();await Promise.all(urls.map(async url=>{let part=caseCache.get(url);if(!part){part=await fetchCohortJSON(url);if(part.detailRunId!==d.detailRunId)throw Error('Case detail version differs; reload this view.');if(part.careerEncoding==='career-pool-v1')unpackCaseRows077(part.rows,d.careerDictionary);caseCache.set(url,part);while(caseCache.size>8)caseCache.delete(caseCache.keys().next().value);}for(const r of part.rows){for(const q of r.questionChanges||[])Object.assign(q,d.questionDictionary[q.type+':'+q.questionId]);details.set(r.id,r);}}));if(epoch!==renderEpoch)return;visible=visible.map(r=>details.get(r.id));if(visible.some(r=>!r))throw Error('A selected case is missing from its detail shard.');}
